INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9613, 'koKR', 'Wycofane: Wola Keanny', '<Gdy dotykasz miecza, słyszysz kobiecy głos, który zwraca się do ciebie>$B$BAu! Nie rób tego! Nie widzisz, że jestem w kawałkach? To naprawdę boli.$B$BWidzę, że Karazhan cię nie uwięził. W takim razie musisz wiedzieć o Khadgarze i Purpurowym Oku.$B$BMusisz znaleźć kogoś, kto złoży mnie z powrotem. Koren... był kiedyś naszym agentem... jest niedaleko. Mam nadzieję, że stoisz po naszej stronie. Jeśli tak, on może pomóc!', 'Strzaskane ostrze, które $gznalazłeś:znalazłaś; w Karazhanie, chce, żebyś $gpoprosił:poprosiła; Korena o jego naprawę. Aby ukończyć to zadanie, musisz też zdobyć u Purpurowego Oka reputację na poziomie Szanowany.', '', '', '', '', '', '', 0),
(9614, 'koKR', 'Wycofane: Przekucie krótkiego ostrza', 'Ta broń została rozbita na tyle kawałków... złożenie jej z powrotem nie będzie łatwe.$B$BBędę potrzebować khorium. Mnóstwa khorium. Potrzebuję też kryształu Pustki i trochę pierwotnego ognia.', 'Przynieś 40 sztabek khorium, 1 kryształ Pustki i 8 pierwotnych ogni Korenowi w Karazhanie.', '', 'Wróć do Korena w Karazhanie.', '', '', '', '', 0),
(9615, 'koKR', 'Wycofane: Przekucie długiego ostrza', 'Ta broń została rozbita na tyle kawałków... złożenie jej z powrotem nie będzie łatwe.$B$BBędę potrzebować khorium. Mnóstwa khorium. Potrzebuję też kryształu Pustki i trochę pierwotnego ognia.', 'Przynieś 40 sztabek khorium, 1 kryształ Pustki i 8 pierwotnych ogni Korenowi w Karazhanie.', '', 'Wróć do Korena w Karazhanie.', '', '', '', '', 0),
(9630, 'koKR', 'Dziennik Medivha', 'Twoje imię krąży po świecie, $N. $GWszedłeś:Weszłaś; do Karazhanu i z niego $gwyszedłeś:wyszłaś; – niewielu śmiertelników może się tym pochwalić.$B$BMuszę cię prosić o szczególną przysługę. W ramach naszych badań Purpurowe Oko próbuje odnaleźć osobisty dziennik Medivha.$B$BNiestety żaden z agentów, których wysłaliśmy do środka, nie wrócił. Ostatni był Wravien. Spróbuj go odnaleźć i dowiedz się, czy ma jakieś wskazówki co do dziennika.', 'Arcymag Alturus na Przełęczy Wichrowej Zguby chce, żebyś $gwszedł:weszła; do Karazhanu i $gporozmawiał:porozmawiała; z Wravienem.', '', '', '', '', '', '', 0),
(9631, 'koKR', 'Pomoc koleżanki po fachu', 'Jest pewien drobiazg, którego nie wziąłem pod uwagę. Pozostałość esencji Medivha w tym fragmencie kości jest całkowicie pozbawiona życia – tak samo jak Arcanagos.$B$BIstnieje jednak sposób. I wiem, kto może nam pomóc.$B$BUdaj się do Strefy 52 w Burzy Otchłani i pokaż fragment kości Kalynnie Lathred. Ona będzie wiedziała, co robić.', 'Zanieś fragment zwęglonej kości Kalynnie Lathred w Strefie 52 w Burzy Otchłani.', '', '', '', '', '', '', 0),
(9637, 'koKR', 'Prośba Kalynny', 'Opuściłam Kirin Tor w pogoni za wiedzą, której mój zakon zakazywał. To więcej niż ironia, że teraz proszą mnie o pomoc właśnie tą wiedzą.$B$BJeśli mam wyświadczyć ci tę przysługę, najpierw musisz zrobić coś dla mnie. Chcę, żebyś $gzdobył:zdobyła; dwie księgi, których szukam.$B$BPierwsza nazywa się Księga zmierzchu i należy do orkowego czarnoksiężnika Nethekurse\'a. Druga, znana jako Księga zapomnianych imion, należy do arakkoa zwanego Tkaczem Mroku Sythem.', 'Kalynna Lathred chce, żebyś $gzdobył:zdobyła; Księgę zmierzchu od Wielkiego Czarnoksiężnika Nethekurse\'a w Strzaskanych Salach Cytadeli Piekielnego Ognia oraz Księgę zapomnianych imion od Tkacza Mroku Sytha w Salach Sethekk w Auchindoun.$B$BTo zadanie trzeba ukończyć na poziomie heroicznym.', '', 'Wróć do Kalynny Lathred w Burzy Otchłani.', '', '', '', '', 0),
(9638, 'koKR', 'W dobrych rękach', 'Miałem szukać tego dziennika? Niemożliwe... Nie całkiem pamiętam...$B$BAleż oczywiście! Chodzi ci o Gradava. Szukał tej księgi, kiedy tu przybyłem. Na pewno już ją znalazł. Może zapytasz go o nią?$B$BPomógłbym ci... ale te księgi są takie... ciekawe!', 'Porozmawiaj z Gradavem w Bibliotece Strażnika w Karazhanie.', '', '', '', '', '', '', 0),
(9639, 'koKR', 'Kamsis', 'Dziennik? Jaki dziennik? Na pewno chodzi ci o Kamsis.$B$BIdź i ją zapytaj. Nie mogę teraz zostawić swojego projektu, bo cała moja praca pójdzie na marne!', 'Porozmawiaj z Kamsis w Bibliotece Strażnika w Karazhanie.', '', '', '', '', '', '', 0),
(9640, 'koKR', 'Widmo Arana', 'Daj mi chwilę pomyśleć. Purpurowe Oko... Dziennik Medivha... Ależ tak, wszystko mi się przypomina.$B$BChyba miałam ten dziennik, którego szukasz, zanim zaczęłam czytać te zwoje...$B$BAran... tak, Aran poprosił mnie o tę księgę. I to tak grzecznie. Po prostu musiałam mu ją dać. W końcu jest ojcem Medivha, $gwiedziałeś:wiedziałaś; o tym?', 'Zdobądź Dziennik Medivha i wróć do Kamsis w Bibliotece Strażnika w Karazhanie.', '', 'Wróć do Kamsis w Karazhanie.', '', '', '', '', 0),
(9644, 'koKR', 'Pożeracz Nocy', '$GWywiązałeś:Wywiązałaś; się ze swojej części umowy. Teraz zwiążę twoją esencję z esencją martwego błękitnego smoka.$B$BNa Tarasie Mistrza stoi urna. Gdy jej dotkniesz, uwolnisz jej energię i przywrócisz do życia zwęglone szczątki Arcanagosa. Pokonaj tę istotę i natychmiast zabierz jej esencję! Musisz zanieść ją Alturusowi.$B$BJeśli zawiedziesz, gwiazdy przepowiadają, że wypuścisz na niebo wielką grozę.$B$BGrozę zwaną Pożeraczem Nocy!', 'Udaj się na Taras Mistrza w Karazhanie i dotknij Poczerniałej urny, aby przywołać Pożeracza Nocy. Zabierz słabą tajemną esencję ze zwłok Pożeracza Nocy i zanieś ją arcymagowi Alturusowi.', '', 'Wróć do arcymaga Alturusa na Przełęczy Wichrowej Zguby.', '', '', '', '', 0),
(9645, 'koKR', 'Taras Mistrza', 'Dziennik? Jaki dziennik?$B$BAch, no tak. Ten dziennik! Purpurowe Oko przysłało mnie tu po niego. Wszystko mi się przypomina.$B$B<Kamsis wskazuje stronę w dzienniku.>$B$BTo jest strona, która interesuje Alturusa. Czy wiesz, że choć dzienniki innych ludzi są zapisem ich wspomnień, dziennik Medivha jest nim dosłownie?$B$BSpróbuj. Idź na Taras Mistrza i przeczytaj tę stronę, a zobaczysz, o co mi chodzi. Przy okazji możesz zdać raport Alturusowi. Obawiam się, że zostanę tu jeszcze jakiś czas.', 'Udaj się na Taras Mistrza w Karazhanie i przeczytaj Dziennik Medivha. Po wykonaniu tego zadania wróć z Dziennikiem Medivha do arcymaga Alturusa.', 'Wpis w dzienniku przeczytany', '', '', '', '', '', 0),
(9650, 'koKR', 'Wycofane: Magiczne wzmocnienie', '<TXT>Tak, wzmocnijmy moje magiczne właściwości. To ma sens. W końcu za życia byłam czarodziejką.$B$BTo, że czyjeś fizyczne naczynie jest bronią, nie czyni tej osoby od razu prostakiem.$B$BBędę potrzebować, żebyś $gzebrał:zebrała; trochę materiałów.', '', '', '', '', '', '', '', 0),
(9651, 'koKR', 'Wycofane: Magiczne wzmocnienie', '<TXT>Tak, wzmocnijmy moje magiczne właściwości. To ma sens. W końcu za życia byłam czarodziejką.$B$BTo, że czyjeś fizyczne naczynie jest bronią, nie czyni tej osoby od razu prostakiem.$B$BBędę potrzebować, żebyś $gzebrał:zebrała; trochę materiałów.', '', '', '', '', '', '', '', 0),
(9652, 'koKR', 'Wycofane: Fizyczne ulepszenie', 'Nie miałabym nic przeciwko. Równie dobrze możemy wycisnąć ze swojej sytuacji, ile się da... w moim przypadku z bycia bronią. Równie dobrze mogę stać się najlepszą bronią, jaką potrafię.$B$BTak, zróbmy to. Ostrzejsza krawędź, solidniejsza rękojeść... Podoba mi się, jak to brzmi.$B$BBędę potrzebować, żebyś $gzebrał:zebrała; dla mnie kilka rzeczy.', '', '', 'Wróć do Cząstki Keanny.', '', '', '', '', 0),
(9653, 'koKR', 'Wycofane: Fizyczne ulepszenie', 'Nie miałabym nic przeciwko. Równie dobrze możemy wycisnąć ze swojej sytuacji, ile się da... w moim przypadku z bycia bronią. Równie dobrze mogę stać się najlepszą bronią, jaką potrafię.$B$BTak, zróbmy to. Ostrzejsza krawędź, solidniejsza rękojeść... Podoba mi się, jak to brzmi.$B$BBędę potrzebować, żebyś $gzebrał:zebrała; dla mnie kilka rzeczy.', '', '', 'Wróć do Cząstki Keanny.', '', '', '', '', 0),
(9654, 'koKR', 'Wycofane: Wszechstronna obrona', 'Magia ofensywna była moją specjalnością... tyle pamiętam. Zrobię, co w mojej mocy, żeby dodać moje moce tajemnego skupienia do twoich.$B$BBędę jednak potrzebować więcej surowej mocy, niż mam teraz. Tajemne anomalie, które krążą po wyższych poziomach Biblioteki Strażnika, będą doskonałym celem. Zbieraj ich tajemne pozostałości – będzie nam ich trzeba dużo.', 'Cząstka Keanny zamknięta w Woli Keanny chce, żebyś $gzebrał:zebrała; 20 tajemnych pozostałości z tajemnych anomalii w Karazhanie.', '', 'Wróć do Cząstki Keanny.', '', '', '', '', 0),
(9655, 'koKR', 'Wycofane: Wzmocnienie leczenia', 'Magia ofensywna była moją specjalnością... tyle pamiętam. Zrobię, co w mojej mocy, żeby dodać moje moce tajemnego skupienia do twoich.$B$BBędę jednak potrzebować więcej surowej mocy, niż mam teraz. Tajemne anomalie, które krążą po wyższych poziomach Biblioteki Strażnika, będą doskonałym celem. Zbieraj ich tajemne pozostałości – będzie nam ich trzeba dużo.', 'Cząstka Keanny zamknięta w Woli Keanny chce, żebyś $gzebrał:zebrała; 20 tajemnych pozostałości z tajemnych anomalii w Karazhanie.', '', 'Wróć do Cząstki Keanny.', '', '', '', '', 0),
(9656, 'koKR', 'Wycofane: Najpierw zabójczość', 'Magia ofensywna była moją specjalnością... tyle pamiętam. Zrobię, co w mojej mocy, żeby dodać moje moce tajemnego skupienia do twoich.$B$BBędę jednak potrzebować więcej surowej mocy, niż mam teraz. Tajemne anomalie, które krążą po wyższych poziomach Biblioteki Strażnika, będą doskonałym celem. Zbieraj ich tajemne pozostałości – będzie nam ich trzeba dużo.', 'Cząstka Keanny zamknięta w Woli Keanny chce, żebyś $gzebrał:zebrała; 20 tajemnych pozostałości z tajemnych anomalii w Karazhanie.', '', 'Wróć do Cząstki Keanny.', '', '', '', '', 0),
(9657, 'koKR', 'Wycofane: Ofensywne skupienie', 'Magia ofensywna była moją specjalnością... tyle pamiętam. Zrobię, co w mojej mocy, żeby dodać moje moce tajemnego skupienia do twoich.$B$BBędę jednak potrzebować więcej surowej mocy, niż mam teraz. Tajemne anomalie, które krążą po wyższych poziomach Biblioteki Strażnika, będą doskonałym celem. Zbieraj ich tajemne pozostałości – będzie nam ich trzeba dużo.', 'Cząstka Keanny zamknięta w Woli Keanny chce, żebyś $gzebrał:zebrała; 20 tajemnych pozostałości z tajemnych anomalii w Karazhanie.', '', 'Wróć do Cząstki Keanny.', '', '', '', '', 0),
(9658, 'koKR', 'Wycofane: Ofensywne skupienie', 'Magia ofensywna była moją specjalnością... tyle pamiętam. Zrobię, co w mojej mocy, żeby dodać moje moce tajemnego skupienia do twoich.$B$BBędę jednak potrzebować więcej surowej mocy, niż mam teraz. Tajemne anomalie, które krążą po wyższych poziomach Biblioteki Strażnika, będą doskonałym celem. Zbieraj ich tajemne pozostałości – będzie nam ich trzeba dużo.', 'Cząstka Keanny zamknięta w Woli Keanny chce, żebyś $gzebrał:zebrała; 20 tajemnych pozostałości z tajemnych anomalii w Karazhanie.', '', 'Wróć do Cząstki Keanny.', '', '', '', '', 0),
(9659, 'koKR', 'Wycofane: Wzmocnienie leczenia', 'Magia ofensywna była moją specjalnością... tyle pamiętam. Zrobię, co w mojej mocy, żeby dodać moje moce tajemnego skupienia do twoich.$B$BBędę jednak potrzebować więcej surowej mocy, niż mam teraz. Tajemne anomalie, które krążą po wyższych poziomach Biblioteki Strażnika, będą doskonałym celem. Zbieraj ich tajemne pozostałości – będzie nam ich trzeba dużo.', 'Cząstka Keanny zamknięta w Woli Keanny chce, żebyś $gzebrał:zebrała; 20 tajemnych pozostałości z tajemnych anomalii w Karazhanie.', '', 'Wróć do Cząstki Keanny.', '', '', '', '', 0),
(9660, 'koKR', 'Wycofane: Najpierw zabójczość', 'Magia ofensywna była moją specjalnością... tyle pamiętam. Zrobię, co w mojej mocy, żeby dodać moje moce tajemnego skupienia do twoich.$B$BBędę jednak potrzebować więcej surowej mocy, niż mam teraz. Tajemne anomalie, które krążą po wyższych poziomach Biblioteki Strażnika, będą doskonałym celem. Zbieraj ich tajemne pozostałości – będzie nam ich trzeba dużo.', 'Cząstka Keanny zamknięta w Woli Keanny chce, żebyś $gzebrał:zebrała; 20 tajemnych pozostałości z tajemnych anomalii w Karazhanie.', '', 'Wróć do Cząstki Keanny.', '', '', '', '', 0),
(9661, 'koKR', 'Wycofane: Wszechstronna obrona', 'Magia ofensywna była moją specjalnością... tyle pamiętam. Zrobię, co w mojej mocy, żeby dodać moje moce tajemnego skupienia do twoich.$B$BBędę jednak potrzebować więcej surowej mocy, niż mam teraz. Tajemne anomalie, które krążą po wyższych poziomach Biblioteki Strażnika, będą doskonałym celem. Zbieraj ich tajemne pozostałości – będzie nam ich trzeba dużo.', 'Cząstka Keanny zamknięta w Woli Keanny chce, żebyś $gzebrał:zebrała; 20 tajemnych pozostałości z tajemnych anomalii w Karazhanie.', '', 'Wróć do Cząstki Keanny.', '', '', '', '', 0),
(9662, 'koKR', 'Wycofane: Wolność Keanny', 'Moje wspomnienia... Teraz pamiętam wszystko! Mój umysł jest jak układanka, która nagle wskoczyła na swoje miejsce.$B$BByłam jedną z pierwszych osób wysłanych do zbadania Karazhanu po tym, jak się zmienił. Demon Malkezar odkrył moje wtargnięcie.$B$BSzybko zrozumiałam, że nie mam z nim szans. Poczułam, jak jego magia więzi moją duszę.$B$BW ostatniej chwili ukryłam cząstkę siebie... swoich wspomnień w jedynym miejscu, jakie przyszło mi do głowy: w mojej broni. Malkezar ma moją duszę. Musisz pomóc mi ją odzyskać!', 'Pokonaj Malkezara w Karazhanie, mając przy sobie Wolę Keanny. Cząstka Keanny musi przetrwać.', '', 'Wróć do Cząstki Keanny.', '', '', '', '', 0),
(9680, 'koKR', 'Odkopując przeszłość', 'Kamsis miała rację! Te informacje są niezwykle ważne.$B$BJeśli Medivh wplótł własną esencję w magię, którą pokonał smoka, całkiem możliwe, że zdołamy odzyskać ze szczątków smoka choćby słabą pozostałość tej esencji. Jakież to cenne odkrycia mogą kryć się pod popiołami Przełęczy Wichrowej Zguby.$B$BUdaj się w góry na południe od Karazhanu i przynieś mi fragment kości, który wygląda na smoczy.', 'Arcymag Alturus chce, żebyś $gudał:udała; się w góry na południe od Karazhanu na Przełęczy Wichrowej Zguby i $gprzyniósł:przyniosła; fragment zwęglonej kości.', '', 'Wróć do arcymaga Alturusa na Przełęczy Wichrowej Zguby.', '', '', '', '', 0),
(9824, 'koKR', 'Tajemne zakłócenia', 'Próbuję uzyskać odcisk energii Karazhanu... do osobistego projektu, rzecz jasna. Niestety tu na górze niczego nie wychwytuję. Gdybym mógł zbliżyć się do podziemnego źródła wody, mój kryształ odbierałby sygnały znacznie wyraźniej.$B$BSłyszałem o podziemnym stawie, a także o studni w piwnicy pod nami. Całe to miejsce roi się jednak od duchów, a wyprawa tam byłaby niebezpieczna dla kogoś w moim wieku. Co ty na to? Pomożesz staremu człowiekowi i przeprowadzisz za mnie wróżenie?', 'Użyj Fioletowego kryształu wróżebnego w pobliżu podziemnych źródeł wody w Piwnicy Mistrza i wróć do arcymaga Alturusa przed Karazhanem.', '', 'Wróć do arcymaga Alturusa na Przełęczy Wichrowej Zguby.', 'Odczyt przy podziemnej studni', 'Odczyt przy podziemnym stawie', '', '', 0),
(9825, 'koKR', 'Niespokojne duchy', 'Jak pewnie $gzauważyłeś:zauważyłaś;, wokół Karazhanu roi się od upiornych istot. Przyczyna ich istnienia jest nieznana, a niewiadome mnie niepokoją!$B$BPrzynieś mi ich upiorne esencje, abym mógł zbadać ich naturę. Karazhan skrywa wiele tajemnic, $N. Jestem zdecydowany odkryć je wszystkie.', 'Przynieś 10 upiornych esencji arcymagowi Alturusowi przed Karazhanem.', '', 'Wróć do arcymaga Alturusa na Przełęczy Wichrowej Zguby.', '', '', '', '', 0),
(9838, 'koKR', 'Purpurowe Oko', 'Spoczęła na tobie wielka odpowiedzialność, $N. Jeśli można ufać znakom, które dostrzegło Purpurowe Oko, musisz im pomóc.$B$BChoć w wielu sprawach nie zgadzam się z Cedrikiem, praca takich ludzi jak Alturus wciąż jest ważna. Uważaj jednak, żeby cię nie wykorzystali. Pamiętaj, że to z tobą związany jest klucz, nie z nimi. Ale jeśli niebezpieczeństwo w Karazhanie jest prawdziwe, to właśnie oni najlepiej pokierują cię w walce z nim. Wróć do Alturusa i pomóż mu, jak tylko możesz.', 'Porozmawiaj z arcymagiem Alturusem przed Karazhanem.', '', '', '', '', '', '', 0),
(9840, 'koKR', 'Rozpoznanie sytuacji', 'Teraz, gdy znaleźliśmy drogę z powrotem do wieży Medivha – a raczej ty ją $gznalazłeś:znalazłaś; – najpierw musimy się zorientować, jak wygląda sytuacja w środku.$B$BJedna z naszych agentek, której udało się przeniknąć do Karazhanu, prowadziła zaszyfrowany dziennik swoich obserwacji. Niestety jej śmierć potwierdzono na krótko przed zamknięciem Karazhanu. Koren, kowal Karazhanu, był na naszym żołdzie. Choć nie należy do Purpurowego Oka, powinien pomóc nam znaleźć dziennik Keanny. Poszukaj go w środku.', 'Odszukaj Korena w Karazhanie.', '', '', '', '', '', '', 0),
(9843, 'koKR', 'Dziennik Keanny', 'Kogo to, mówisz, szukasz? Keanny?$B$BPoznałem kiedyś kogoś o tym imieniu. Mieszkała w komnatach gościnnych na górze. Chyba miałem to zachować w tajemnicy, prawda?$B$BMówisz, że jesteś z Purpurowego Oka? Nie, nigdy o nich nie słyszałem.$B$BJeśli pozwolisz, muszę wrócić do pracy.$B$B<Koren chyba już o tobie zapomniał.>', 'Przeszukaj Komnaty Gościnne w Karazhanie w poszukiwaniu Dziennika Keanny i zanieś go arcymagowi Alturusowi przed Karazhanem.', '', 'Wróć do arcymaga Alturusa na Przełęczy Wichrowej Zguby.', '', '', '', '', 0),
(9844, 'koKR', 'Demoniczna obecność', 'Ostatnie wpisy Keanny potwierdzają nasze podejrzenia co do demonicznej obecności w Karazhanie.$B$BWykryła przybycie agenta Płonącego Legionu, który według jej opisu zjawił się na szczycie wieży.$B$BNa tym jej wpisy się kończą.$B$BKarazhan to bardzo ważne miejsce, $N. To wrota do Otchłani, latarnia świecąca w inne światy. Możliwe skutki tego, że wpadnie w niepowołane ręce, są nie do pomyślenia. To demoniczne wtargnięcie trzeba powstrzymać. A ty, $N, jako jedyna osoba masz klucz.', 'Arcymag Alturus chce, żebyś $gzniszczył:zniszczyła; demoniczną obecność na szczycie Karazhanu.', '', 'Wróć do arcymaga Alturusa na Przełęczy Wichrowej Zguby.', 'Demoniczna obecność zniszczona', '', '', '', 0),
(10725, 'koKR', 'Dostojeństwo w Purpurowym Oku', 'Twoje zasługi przerosły wszystko, czego od ciebie oczekiwano, $N. Dzieli cię już tylko krok od najwyższego zaszczytu, jaki może spotkać kogoś, kto nie jest obywatelem Dalaranu.$B$BNadal dowodź nam swojej lojalności, a wzmocnię twój sygnet do pełni jego możliwości.', 'Gdy zdobędziesz u Purpurowego Oka reputację na poziomie Wywyższony, przynieś swój purpurowy sygnet arcymagini Lerydzie na Przełęczy Wichrowej Zguby.', '', '', '', '', '', '', 0),
(10726, 'koKR', 'Dostojeństwo w Purpurowym Oku', 'Twoje zasługi przerosły wszystko, czego od ciebie oczekiwano, $N. Dzieli cię już tylko krok od najwyższego zaszczytu, jaki może spotkać kogoś, kto nie jest obywatelem Dalaranu.$B$BNadal dowodź nam swojej lojalności, a wzmocnię twój sygnet do pełni jego możliwości.', 'Gdy zdobędziesz u Purpurowego Oka reputację na poziomie Wywyższony, przynieś swój purpurowy sygnet arcymagini Lerydzie na Przełęczy Wichrowej Zguby.', '', '', '', '', '', '', 0),
