(10738, 'koKR', 'Wybitna służba', 'Nie $gzawiodłeś:zawiodłaś; nas, $N. Wciąż jednak wiążemy z tobą wielkie nadzieje.$B$BSłuż dalej Purpurowemu Oku, a zostaniesz należycie $gwynagrodzony:wynagrodzona;.', 'Gdy zdobędziesz u Purpurowego Oka reputację na poziomie Czczony, przynieś swój purpurowy sygnet arcymagini Lerydzie na Przełęczy Wichrowej Zguby.', '', '', '', '', '', '', 0),
(10739, 'koKR', 'Wybitna służba', 'Nie $gzawiodłeś:zawiodłaś; nas, $N. Wciąż jednak wiążemy z tobą wielkie nadzieje.$B$BSłuż dalej Purpurowemu Oku, a zostaniesz należycie $gwynagrodzony:wynagrodzona;.', 'Gdy zdobędziesz u Purpurowego Oka reputację na poziomie Czczony, przynieś swój purpurowy sygnet arcymagini Lerydzie na Przełęczy Wichrowej Zguby.', '', '', '', '', '', '', 0),
(10740, 'koKR', 'Wybitna służba', 'Nie $gzawiodłeś:zawiodłaś; nas, $N. Wciąż jednak wiążemy z tobą wielkie nadzieje.$B$BSłuż dalej Purpurowemu Oku, a zostaniesz należycie $gwynagrodzony:wynagrodzona;.', 'Gdy zdobędziesz u Purpurowego Oka reputację na poziomie Czczony, przynieś swój purpurowy sygnet arcymagini Lerydzie na Przełęczy Wichrowej Zguby.', '', '', '', '', '', '', 0),
(10741, 'koKR', 'Wybitna służba', 'Nie $gzawiodłeś:zawiodłaś; nas, $N. Wciąż jednak wiążemy z tobą wielkie nadzieje.$B$BSłuż dalej Purpurowemu Oku, a zostaniesz należycie $gwynagrodzony:wynagrodzona;.', 'Gdy zdobędziesz u Purpurowego Oka reputację na poziomie Czczony, przynieś swój purpurowy sygnet arcymagini Lerydzie na Przełęczy Wichrowej Zguby.', '', '', '', '', '', '', 0),
(11031, 'koKR', 'Koniec z arcymagiem', '', '', '', 'Wróć do arcymagini Lerydy na Przełęczy Wichrowej Zguby.', '', '', '', '', 0),
(11032, 'koKR', 'Koniec z obrońcą', '', '', '', 'Wróć do arcymagini Lerydy na Przełęczy Wichrowej Zguby.', '', '', '', '', 0),
(11033, 'koKR', 'Koniec z zabójcą', '', '', '', 'Wróć do arcymagini Lerydy na Przełęczy Wichrowej Zguby.', '', '', '', '', 0),
(11034, 'koKR', '', '', '', '', 'Wróć do arcymagini Lerydy na Przełęczy Wichrowej Zguby.', '', '', '', '', 0),
(11216, 'koKR', 'Arcymag Alturus', 'Mój mentor przysłał mnie tu, żebym poszukał pomocy, ale niestety nie wolno mi wychodzić poza Dolne Miasto, a bywalcy tego przybytku raczej nie kwapią się do pomocy.$B$BTy wydajesz się inny – bardziej w typie poszukiwacza przygód. Jeśli chcesz wesprzeć naszą sprawę, porozmawiaj z arcymagiem Alturusem przed dawną siedzibą Medivha, Karazhanem.$B$BTymczasem ja spróbuję uzyskać dostęp do reszty miasta. Podobno przebywa tu jeden z naszych dawnych współpracowników.', 'Porozmawiaj z arcymagiem Alturusem przed Karazhanem na Przełęczy Wichrowej Zguby.', '', '', '', '', '', '', 0),
(12616, 'koKR', 'Komnata tajemnic', 'Doskonale, $gdoświadczony poszukiwacz:doświadczona poszukiwaczka; przygód. Właśnie kogoś takiego potrzebujemy.$b$bMagowie Kirin Toru strzegący wieży Medivha mówią, że w Karazhanie dzieje się coś złego. Czai się tam nowa moc, która nie podlega ani magii Strażnika, ani Legionowi. Z tego, co zdołali wybadać, to elfi książę o imieniu Tenris Mrokokrwisty i są powody sądzić, że służy Pladze.$b$bIdź, $gprzyjacielu:przyjaciółko;, zbadaj komnatę Mrokokrwistego i wróć z wszelkimi informacjami, jakie znajdziesz.', 'Emisariusz Argentowego Brzasku chce, żebyś $gprzeszukał:przeszukała; komnatę Tenrisa Mrokokrwistego w Kwaterach Służby w Karazhanie.', '', 'Wróć do Emisariusza Argentowego Brzasku.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9630, 'koKR', 'Ogrom wiedzy... Mógłbym tu spędzić całe lata! Dalaran na pewno zrozumie...', 0),
(9631, 'koKR', 'Alturus chce wskrzesić całego smoka? To zadanie, którego przy najlepszych chęciach nie można nazwać łatwym.$B$BPomówmy, jak możemy sobie nawzajem pomóc, $N.', 0),
(9637, 'koKR', 'Doskonale, $N. Od bardzo dawna próbowałam zdobyć te księgi. Dobrze się składa, że mogłyśmy sobie nawzajem pomóc.', 0),
(9638, 'koKR', 'Nie widzisz, że jestem w trakcie pracy? Czego chcesz?', 0),
(9639, 'koKR', 'Ten dziennik, o którym mówisz... Przysłano mnie tu, żebym go szukała, prawda?', 0),
(9640, 'koKR', '$GZnalazłeś:Znalazłaś; to, czego $gszukałeś:szukałaś;? Bo czegoś $gszukałeś:szukałaś;, prawda?', 0),
(9644, 'koKR', 'To zdumiewające! Nie tylko $gprzyniosłeś:przyniosłaś; Dziennik Medivha, ale też $gzdobyłeś:zdobyłaś; fragment jego własnej esencji.$B$BChoć ta resztka esencji jest słaba, ujawni nam kluczowe informacje o Medivhu. Nie zapomnimy ci tego, $N.', 0),
(9645, 'koKR', 'Szkoda, że wysłani przez nas agenci ulegli magii Karazhanu. Przynajmniej tobie udało się zdobyć to, po co przyszli.', 0),
(9680, 'koKR', 'Doskonale! Choć ten fragment jest niewielki, aż kipi od energii, czuję to!', 0),
(9824, 'koKR', 'Te odczyty nie wróżą nic dobrego, $N. Z Karazhanu powinny płynąć najróżniejsze prądy tajemnej mocy... a zamiast tego stał się ogromną energetyczną próżnią. Żadnych sygnałów. Nic. Poza bardzo słabym demonicznym echem.$B$BTo złe wieści, $N.', 0),
(9825, 'koKR', 'Fascynujące. Zbadam te esencje, $N. Dziękuję ci za pomoc.', 0),
(9838, 'koKR', 'Wysłałem cię z raportem, a ty wracasz z kluczem do tego miejsca? Musi być w tobie więcej, niż widać na pierwszy rzut oka, $N.', 0),
(9840, 'koKR', '<Koren patrzy na ciebie niepewnie.>$B$BNic nie wiem o żadnym Purpurowym Oku, o którym mówisz. Jestem tylko kowalem.', 0),
(9843, 'koKR', '$GZnalazłeś:Znalazłaś; dziennik. Mam nadzieję, że są w nim potrzebne nam informacje, $N.', 0),
(9844, 'koKR', 'Udało ci się! Tak, odczyty znów wracają do normy!$B$BMusimy przekazać tę wiadomość Cedricowi. Twoje osiągnięcie zrobi na nim wielkie wrażenie.', 0),
(10725, 'koKR', 'Sygnet, który teraz trzymasz, jest równie potężny jak sygnet każdego arcymaga Rady. Noś go, dokądkolwiek się udasz, aby wtajemniczeni rozpoznali, komu służysz. Noś go, dokądkolwiek się udasz, aby jego moc służyła tobie tak, jak ty służysz nam!', 0),
(10726, 'koKR', 'Sygnet, który teraz trzymasz, jest równie potężny jak sygnet każdego arcymaga Rady. Noś go, dokądkolwiek się udasz, aby wtajemniczeni rozpoznali, komu służysz. Noś go, dokądkolwiek się udasz, aby jego moc służyła tobie tak, jak ty służysz nam!', 0),
(10727, 'koKR', 'Sygnet, który teraz trzymasz, jest równie potężny jak sygnet każdego arcymaga Rady. Noś go, dokądkolwiek się udasz, aby wtajemniczeni rozpoznali, komu służysz. Noś go, dokądkolwiek się udasz, aby jego moc służyła tobie tak, jak ty służysz nam!', 0),
(10728, 'koKR', 'Sygnet, który teraz trzymasz, jest równie potężny jak sygnet każdego arcymaga Rady. Noś go, dokądkolwiek się udasz, aby wtajemniczeni rozpoznali, komu służysz. Noś go, dokądkolwiek się udasz, aby jego moc służyła tobie tak, jak ty służysz nam!', 0),
(10729, 'koKR', 'Czy jesteś $gpewien:pewna; swojego wyboru, $N? To nie jest decyzja, którą można podjąć lekko.$B$BPurpurowy sygnet będzie zyskiwał moc, w miarę jak będziesz dowodzić swojej wartości Purpurowemu Oku.', 0),
(10730, 'koKR', 'Czy jesteś $gpewien:pewna; swojego wyboru, $N? To nie jest decyzja, którą można podjąć lekko.$B$BPurpurowy sygnet będzie zyskiwał moc, w miarę jak będziesz dowodzić swojej wartości Purpurowemu Oku.', 0),
(10731, 'koKR', 'Czy jesteś $gpewien:pewna; swojego wyboru, $N? To nie jest decyzja, którą można podjąć lekko.$B$BPurpurowy sygnet będzie zyskiwał moc, w miarę jak będziesz dowodzić swojej wartości Purpurowemu Oku.', 0),
(10732, 'koKR', 'Czy jesteś $gpewien:pewna; swojego wyboru, $N? To nie jest decyzja, którą można podjąć lekko.$B$BPurpurowy sygnet będzie zyskiwał moc, w miarę jak będziesz dowodzić swojej wartości Purpurowemu Oku.', 0),
(10733, 'koKR', 'Zaszczycasz nas swoją służbą, $N. Patrz, jak uwalniam moc zawartą w twoim sygnecie!', 0),
(10734, 'koKR', 'Zaszczycasz nas swoją służbą, $N. Patrz, jak uwalniam moc zawartą w twoim sygnecie!', 0),
(10735, 'koKR', 'Zaszczycasz nas swoją służbą, $N. Patrz, jak uwalniam moc zawartą w twoim sygnecie!', 0),
(10736, 'koKR', 'Zaszczycasz nas swoją służbą, $N. Patrz, jak uwalniam moc zawartą w twoim sygnecie!', 0),
(10738, 'koKR', 'Twoja służba nie przeszła bez echa, $N. Twój sygnet może wyglądać tak samo, ale jego moc rośnie, w miarę jak dowodzisz swojej lojalności.', 0),
(10739, 'koKR', 'Twoja służba nie przeszła bez echa, $N. Twój sygnet może wyglądać tak samo, ale jego moc rośnie, w miarę jak dowodzisz swojej lojalności.', 0),
(10740, 'koKR', 'Twoja służba nie przeszła bez echa, $N. Twój sygnet może wyglądać tak samo, ale jego moc rośnie, w miarę jak dowodzisz swojej lojalności.', 0),
(10741, 'koKR', 'Twoja służba nie przeszła bez echa, $N. Twój sygnet może wyglądać tak samo, ale jego moc rośnie, w miarę jak dowodzisz swojej lojalności.', 0),
(11031, 'koKR', 'Tę kolejną decyzję podejmij rozważnie. Staramy się iść naszym sojusznikom na rękę, ale nawet zasoby Dalaranu mają swoje granice.', 0),
(11032, 'koKR', 'Tę kolejną decyzję podejmij rozważnie. Staramy się iść naszym sojusznikom na rękę, ale nawet zasoby Dalaranu mają swoje granice.', 0),
(11033, 'koKR', 'Tę kolejną decyzję podejmij rozważnie. Staramy się iść naszym sojusznikom na rękę, ale nawet zasoby Dalaranu mają swoje granice.', 0),
(11034, 'koKR', 'Tę kolejną decyzję podejmij rozważnie. Staramy się iść naszym sojusznikom na rękę, ale nawet zasoby Dalaranu mają swoje granice.', 0),
(11216, 'koKR', 'Dziękuję, że $gznalazłeś:znalazłaś; czas, by przyjść nam z pomocą. Przed nami ważna praca.', 0),
(12616, 'koKR', 'Jeśli rozkazy, które $gwidziałeś:widziałaś;, są prawdziwe, twoje wieści są naprawdę złowieszcze. Możemy tylko mieć nadzieję, że jego misję przerwano na tyle wcześnie, by wróg nie dowiedział się zbyt wiele o naszych siłach.$b$bDziękuję, $N. Obyś $gbył bezpieczny:była bezpieczna; w tych mrocznych czasach.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(9631, 'koKR', 'Przysyła cię Alturus. Gwiazdy zapowiedziały twoje przybycie.', 0),
(9637, 'koKR', 'Masz księgi, których szukam, $N?', 0),
(9640, 'koKR', 'Czy ty nie $gszukałeś:szukałaś; jakiegoś dziennika czy czegoś takiego?', 0),
(9644, 'koKR', 'Jakie wieści przynosisz, $N?', 0),
(9645, 'koKR', '$GWróciłeś:Wróciłaś;! Jakie wieści przynosisz?', 0),
(9680, 'koKR', 'Masz fragment kości, którego potrzebuję, $N?', 0),
(9824, 'koKR', 'Odczyty, $N. $GWykonałeś:Wykonałaś; je?', 0),
(9825, 'koKR', 'Masz upiorne esencje, których potrzebuję, $N?', 0),
(9843, 'koKR', 'Dziennik Keanny... $gznalazłeś:znalazłaś; go?', 0),
(9844, 'koKR', 'Boję się pytać, $N. Jak wygląda sytuacja w Karazhanie?', 0),
(11031, 'koKR', 'Zmieniasz zdanie co do poprzedniego wyboru? Chyba mogę pomóc ci go odwrócić. Ostatecznie Dalaranowi bardziej zależy na twojej lojalności niż na tym, jak ją okazujesz.$b$bNie będzie to tanie. No i oczywiście będę potrzebować z powrotem twojego starego pierścienia.', 0),
(11032, 'koKR', 'Zmieniasz zdanie co do poprzedniego wyboru? Chyba mogę pomóc ci go odwrócić. Ostatecznie Dalaranowi bardziej zależy na twojej lojalności niż na tym, jak ją okazujesz.$b$bNie będzie to tanie. No i oczywiście będę potrzebować z powrotem twojego starego pierścienia.', 0),
(11033, 'koKR', 'Zmieniasz zdanie co do poprzedniego wyboru? Chyba mogę pomóc ci go odwrócić. Ostatecznie Dalaranowi bardziej zależy na twojej lojalności niż na tym, jak ją okazujesz.$b$bNie będzie to tanie. No i oczywiście będę potrzebować z powrotem twojego starego pierścienia.', 0),
(11034, 'koKR', 'Zmieniasz zdanie co do poprzedniego wyboru? Chyba mogę pomóc ci go odwrócić. Ostatecznie Dalaranowi bardziej zależy na twojej lojalności niż na tym, jak ją okazujesz.$b$bNie będzie to tanie. No i oczywiście będę potrzebować z powrotem twojego starego pierścienia.', 0),
(12616, 'koKR', 'Co $godkryłeś:odkryłaś;?', 0);
