INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(15690, 2, 0, 'koKR', 'Widzę, że subtelność zamysłu przerasta takich prymitywów jak wy.'),
(15690, 3, 0, 'koKR', 'Kto wie, jakie sekrety kryją się w ciemności.'),
(15690, 4, 0, 'koKR', 'Siły niebios są moje, mogę nimi władać wedle woli.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(12109, 'koKR', 'Nadszedł czas, by Horda i Przymierze zwróciły wzrok ku Północnej Grani i inwazji Króla Lisza. W ostatnich dniach zaatakowane zostały ziemie w całym Kalimdorze i we Wschodnich Królestwach. Czy chwycisz za broń, by ocalić swoją ziemię przed zniszczeniem z ich rąk?', '', 0),
(12176, 'koKR', 'Co się dzieje?', 'Co się dzieje?', 0),
(12180, 'koKR', 'Znów nadeszła fala wojny. Z mroźnej północy nekropolie Króla Lisza obległy nasze ziemie. Wysyła latające nekropolie, by najeżdżały cały świat.', '', 0),
(12198, 'koKR', 'Czy Zimozdrój jest teraz atakowany?', 'Czy Zimozdrój jest teraz atakowany?', 0),
(12199, 'koKR', 'Owszem, wzgórza Zimozdroju próbują właśnie odeprzeć ponowny szturm Plagi. Twoja pomoc bardzo by się im przydała.$B$BPozostałe nekropolie: $2284W', '', 0),
(12200, 'koKR', 'Na razie ten obszar jest wolny od wpływów Plagi. Obawiam się, że to tylko kwestia czasu, zanim wrócą.', '', 0),
(12201, 'koKR', 'Czy Tanaris jest teraz atakowany?', 'Czy Tanaris jest teraz atakowany?', 0),
(12202, 'koKR', 'Wygląda na to, że armia Plagi dotarła do Tanaris. Wysłano tam znaczną liczbę nekropolii i innych sił.$B$BPozostałe nekropolie: $2283W', '', 0),
(12203, 'koKR', 'Czy Jałowe Ziemie są teraz atakowane?', 'Czy Jałowe Ziemie są teraz atakowane?', 0),
(12204, 'koKR', 'Plaga szerzy się na Jałowych Ziemiach. Potrzebny jest każdy zdolny do walki wojownik, by powstrzymać falę ich inwazji.$B$BPozostałe nekropolie: $2280W', '', 0),
(12205, 'koKR', 'Czy Płonące Stepy są teraz atakowane?', 'Czy Płonące Stepy są teraz atakowane?', 0),
(12206, 'koKR', 'Jeśli na Płonące Stepy wkrótce nie dotrze dodatkowe wsparcie, obawiam się, że Plaga założy tam bazę wypadową. Jeśli możesz, udaj się tam i wesprzyj obrońców.$B$BPozostałe nekropolie: $2281W', '', 0),
(12207, 'koKR', 'Co mogę zrobić?', 'Co mogę zrobić?', 0),
(12209, 'koKR', 'Plaga zakłada niewielkie punkty zborne w atakowanych miejscach i otrzymuje rozkazy oraz inną pomoc od nekropolii, które przelatują nad nimi. Z tego, co wiemy, jedynym sposobem, by je wykorzenić, jest wybicie sił naziemnych otaczających te punkty.', '', 0),
(12241, 'koKR', 'Mam jeszcze jedno pytanie.', 'Mam jeszcze jedno pytanie.', 0),
(12398, 'koKR', 'Ile bitew wygraliśmy?', 'Ile bitew wygraliśmy?', 0),
(12399, 'koKR', 'Wygraliśmy z Plagą już $2219W bitew. Przygotuj się, $n, bo ta wojna jest daleka od końca.', '', 0),
(12402, 'koKR', 'Wygraliśmy z Plagą już $2219W bitew. Głowa do góry, $n. Choć czeka nas jeszcze wiele bitew, bohaterowie ze wszystkich krain powstali, by je stoczyć.', '', 0),
(12403, 'koKR', 'Wygraliśmy z Plagą już $2219W bitew. Trzymaj się mocno, $n! Musimy wytrwać!', '', 0),
(12434, 'koKR', 'Gdzie walczymy z Plagą?', 'Gdzie walczymy z Plagą?', 0),
(12435, 'koKR', 'Król Lisz wysłał jedynie niewielkie siły przeciwko każdej ze stolic Azeroth, a jego główne siły regularnie atakują następujące krainy:$B$BAszarę, Jałowe Ziemie, Płonące Stepy, pustynię Tanaris, Wschodnie Plagowiska i Zimozdrój.', '', 0),
(12474, 'koKR', 'Plaga szerzy się w Aszarze. Potrzebny jest każdy zdolny do walki wojownik, by powstrzymać falę ich inwazji.$B$BPozostałe nekropolie: $2279W', '', 0),
(12475, 'koKR', 'Plaga szerzy się we Wschodnich Plagowiskach. Potrzebny jest każdy zdolny do walki wojownik, by powstrzymać falę ich inwazji.$B$BPozostałe nekropolie: $2282W', '', 0),
(12476, 'koKR', 'Czy Aszara jest teraz atakowana?', 'Czy Aszara jest teraz atakowana?', 0),
(12477, 'koKR', 'Czy Wschodnie Plagowiska są teraz atakowane?', 'Czy Wschodnie Plagowiska są teraz atakowane?', 0),
(12479, 'koKR', 'Gdzie jeszcze walczymy z Plagą?', 'Gdzie jeszcze walczymy z Plagą?', 0),
(14185, 'koKR', 'Kiedyś służyłem Medivhowi... albo udawałem, że służę. Pomagałem Purpurowemu Oku mieć Mistrza na oku.$B$BAle teraz myślę tylko o... kuciu podków. Wciąż i wciąż.', '', 0),
(14187, 'koKR', 'Więc wiesz o Purpurowym Oku? Może później znajdę dla ciebie czas.$B$BMuszę wracać do pracy.', '', 0),
(14188, 'koKR', 'Potrzebuję twoich umiejętności kowalskich, Korenie.', 'Potrzebuję twoich umiejętności kowalskich, Korenie.', 0),
(15123, 'koKR', 'Nie uznam porażki! Jestem księciem eredarów! Ja... jestem...', '', 0),
(15124, 'koKR', 'Chyba nie sądziliście, że możecie wygrać.', '', 0),
(15125, 'koKR', 'Wasza chciwość, wasza głupota przywiodła was do tego końca.', '', 0),
(15126, 'koKR', 'Jesteście tylko zabawkami. Nie nadajecie się nawet do rozrywki.', '', 0),
(15127, 'koKR', 'Szaleństwo przywiodło was do mnie. Będę waszą zgubą!', '', 0),
(15341, 'koKR', 'Naiwni głupcy! Czas to ogień, w którym spłoniecie!', '', 0),
(15342, 'koKR', 'Jak możecie liczyć, że oprzecie się tak przytłaczającej potędze?', '', 0),
(15343, 'koKR', 'Wszystkie rzeczywistości, wszystkie wymiary stoją przede mną otworem!', '', 0),
(15344, 'koKR', 'Stajecie nie tylko przeciwko Malkezarowi, ale i przeciw legionom, którymi dowodzę!', '', 0),
(18427, 'koKR', 'Jest tutaj... gdzieś... Wiem to. Gdzieś w tej bibliotece jest wiedza, której szukam...', '', 0),
(18428, 'koKR', '', 'Ta wieża to kompletne i skończone szaleństwo. To nie biblioteka, tylko ogromny stóg książek, a igła chyba w ogóle nie istnieje! No dobrze, co to ja miałam robić?', 0),
(18429, 'koKR', 'Twoja obecność przeszkadza w bardzo ważnej pracy. Proszę natychmiast odejść. Na czym to stanęło?', '', 0),
(19699, 'koKR', '', 'Karazhan nie zawsze był tak... złowieszczy. Pomroka spowiła Karazhan dopiero wraz ze śmiercią Medivha. A przynajmniej z tym, co uważamy za śmierć Medivha.', 0);
